import { get, handleApiError, post } from '@helpers/httpClient';

import { mapArticleToFront } from '../@mappers/articles.toFront.mapper';
import {
  IAddArticleDTO,
  IArticleDTO,
  IGetArticlesCriteria,
  IUpdateArticleDTO,
} from '../@types/articles.dto.types';

export const getArticlesAsync = async (criteria: IGetArticlesCriteria = {}) => {
  const res = await get('/ajax/articles/articles_list.php', criteria).then<IArticleDTO[]>(
    handleApiError,
  );
  return res.map(mapArticleToFront);
};

export const getOneArticleAsync = async (id: number) => {
  const res = await get('/ajax/articles/article_one.php', { id }).then(handleApiError);
  return mapArticleToFront(res);
};

export const addArticleAsync = async (article: IAddArticleDTO) => {
  const res = await post('/ajax/articles/article_add.php', article).then<{ id: number }>(
    handleApiError,
  );
  return res.id;
};

export const updateArticleAsync = async (article: IUpdateArticleDTO) => {
  const res = await post('/ajax/articles/article_edit.php', article).then<{ affected: number }>(
    handleApiError,
  );
  return res.affected > 0;
};

export const deleteArticleAsync = async (id: number) => {
  const res = await post('/ajax/articles/article_del.php', { id }).then<{ affected: number }>(
    handleApiError,
  );
  return res.affected > 0;
};
