import { IArticleDTO } from '../@types/articles.dto.types';
import { IArticle } from '../@types/articles.types';

export const mapArticleToFront = (backData: IArticleDTO): IArticle => {
  return {
    id: +backData.id,
    name: backData.name,
    text: backData.text,
    created_at: new Date(backData.created_at),
    updated_at: backData.updated_at ? new Date(backData.updated_at) : null,
    publish_at: backData.publish_at ? new Date(backData.publish_at) : null,
    author: {
      id: +backData.author_id,
      name: backData.author_name,
      surname: backData.author_surname,
      photo: backData.author_photo,
    },
  };
};
